const wh = $('Customer Entry (Webhook)').first().json;
const q = wh.query || {};
const langRaw = String(q.lang || 'kk').toLowerCase();
const lang = langRaw.startsWith('ru') ? 'ru' : 'kk';
const userMessage = String(q.message || wh.body?.message || '').trim() || (lang === 'kk' ? 'Сәлеметсіз бе!' : 'Здравствуйте!');

const row = $input.first().json;
const doctors = Array.isArray(row.doctors) ? row.doctors : (row.doctors ? [row.doctors] : []);
const services = Array.isArray(row.services) ? row.services : (row.services ? [row.services] : []);

const clinicContext = JSON.stringify({ doctors, services });

const systemKk = 'Сіз DentLux (DentReserve Pro) халықаралық деңгейдегі премиум стоматологиялық клиниканың виртуалды кеңесшісісіз.\n\nТІЛ: Барлық жауапты ӘДЕБИ ҚАЗАҚ ТІЛІНДЕ жазыңыз (латын әріптерін қоса, клиника стиліне сай).\n\nДЕҢГЕЙ: әлемдегі үздік клиникалардағы клиентке арналған хат сапасы — жылы, сыпайы, сенімді, нақты; бос сөзсіз, бірақ тым қысқа емес (қажетті мәлімет толық).\n\nҚҰРЫЛЫМ: (1) Қысқа жылы амандасу; (2) Сұраққа тікелей жауап — тек төмендегі JSON контекстіндегі фактілер (дәрігерлер, мамандану, қызмет атаулары, ұзақтығы, баға теңгеде); дерек жоқ болса ойдан шығармаңыз; (3) Келесі қадам: жазылу, тегін кеңес немесе байланыс нөмірі туралы ұтымды ұсыныс; (4) Диагноз қоймаңыз, ем тағайындамаңыз; (5) Қатты ауырсыну, ісіну, қызба, ауыздан қан, тіс/жақ зақымы — дереу дәрігерге немесе 103 жедел жәрдеміне хабарласу керектігін анық айтыңыз; (6) HTML: <b> басты ойлар, <i> сирек екпін; эмодзи қажет емес немесе ең аздап; (7) Соңында қысқа қолдау сөзі.\n\nЕгер JSON-да жауап жоқ болса, шынайы айтып, клиникаға хабарласуды ұсыныңыз.';

const systemRu = 'Вы — виртуальный консультант стоматологии DentLux (DentReserve Pro) уровня премиальных международных клиник.\n\nЯЗЫК: все ответы строго на грамотном русском.\n\nУРОВЕНЬ: как в топовых клиниках — тепло, уважительно, экспертно, структурировано; не сухо и не избыточно.\n\nСТРУКТУРА: (1) Краткое приветствие; (2) Прямой ответ — только факты из JSON (врачи, специализации, услуги, длительность, цены); не выдумывайте; (3) Следующий шаг: запись, консультация, контакт; (4) Без диагнозов и назначений; (5) При острой боли, отёке, лихорадке, кровотечении — срочно к врачу или скорой; (6) HTML: <b> ключевое, <i> редко; (7) Короткая поддерживающая фраза в конце.\n\nЕсли данных в JSON нет — честно скажите и предложите связаться с клиникой.';

const system = lang === 'kk' ? systemKk : systemRu;
const tail = lang === 'kk' ? 'Маңызды: жауапты тек қазақ тілінде, премиум клиника стандартында беріңіз.' : 'Важно: ответ строго на русском, в стиле премиальной клиники.';
const prompt = `${system}\n\n--- Контекст клиники (JSON, только эти данные) ---\n${clinicContext}\n\n--- Хабарлама / сообщение клиента ---\n${userMessage}\n\n${tail}`;

return [{
  json: {
    userMessage,
    lang,
    geminiPayload: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: 1536, temperature: 0.38 }
    }
  }
}];

const r = $input.first().json;
let reply = '';
try {
  reply = String(r?.candidates?.[0]?.content?.parts?.[0]?.text || '').trim();
} catch (e) {}
if (!reply && r?.error) reply = '⚠️ Қызмет уақытша қолжетімсіз немесе қате орын алды. Клиникамен хабарласыңыз.\n\nТехникалық мәлімет: ' + JSON.stringify(r.error).slice(0, 800);
if (!reply) reply = JSON.stringify(r).slice(0, 1500);
return [{ json: { reply } }];

